INSERT INTO posts (user_id, title, content, view_count, created_at, updated_at) VALUES
                                                                                    (4, '오늘의 일상', '오늘의 일상 기록이에요. 출근길에 본 하늘이 너무 예뻐서 사진 찍었고, 일 끝나고 친구랑 맥주 한잔 했습니다. 이런 시간이 참 소중하네요.', 0, '2025-09-18 09:00:00', '2025-09-18 09:00:00'),
                                                                                    (3, '아침 산책 기록', '아침 산책 기록에 대해 적자면, 하루 종일 비가 와서 집에만 있었어요. 유튜브 보면서 쉬었는데 오히려 힐링이 된 것 같아요.', 0, '2025-09-18 09:00:01', '2025-09-18 09:00:01'),
                                                                                    (2, '점심 후기', '점심 후기 기록이에요. 출근길에 본 하늘이 너무 예뻐서 사진 찍었고, 일 끝나고 친구랑 맥주 한잔 했습니다. 이런 시간이 참 소중하네요.', 0, '2025-09-18 09:00:02', '2025-09-18 09:00:02'),
                                                                                    (1, '주말 일기', '주말 일기에 대해 적자면, 하루 종일 비가 와서 집에만 있었어요. 유튜브 보면서 쉬었는데 오히려 힐링이 된 것 같아요.', 0, '2025-09-18 09:00:03', '2025-09-18 09:00:03'),
                                                                                    (3, '비 오는 날 하루', '비 오는 날 하루에 대해 적자면, 하루 종일 비가 와서 집에만 있었어요. 유튜브 보면서 쉬었는데 오히려 힐링이 된 것 같아요.', 0, '2025-09-18 09:00:04', '2025-09-18 09:00:04'),
                                                                                    (2, '하루의 작은 행복', '하루의 작은 행복을 쓰려고 합니다. 오늘은 별일 없었지만, 작은 것에도 감사한 하루였습니다. 점심에 먹은 김치찌개가 유난히 맛있었고, 저녁에는 가족과 함께 산책을 했어요.', 0, '2025-09-18 09:00:05', '2025-09-18 09:00:05'),
                                                                                    (4, '저녁 산책 소감', '저녁 산책 소감에 대해 적자면, 하루 종일 비가 와서 집에만 있었어요. 유튜브 보면서 쉬었는데 오히려 힐링이 된 것 같아요.', 0, '2025-09-18 09:00:06', '2025-09-18 09:00:06'),
                                                                                    (1, '친구와의 만남', '친구와의 만남 기록이에요. 출근길에 본 하늘이 너무 예뻐서 사진 찍었고, 일 끝나고 친구랑 맥주 한잔 했습니다. 이런 시간이 참 소중하네요.', 0, '2025-09-18 09:00:07', '2025-09-18 09:00:07'),
